package ch.xs3.usbphoto;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.provider.DocumentsContract;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 static final int BG=0xff080e16,INK=0xffe7f4ff,MUTED=0xff9cadc2,BLUE=0xff46bfff;
 TextView source,dest,status,detail;Button srcButton,dstButton,copy,cancel;ProgressBar bar;SharedPreferences prefs;Typeface font;
 final Handler handler=new Handler(Looper.getMainLooper());boolean dialogOpen=false;boolean pendingCopy=false;
 String t(String en,String fr){return Words.t(this,en,fr);}
 final Runnable refresh=new Runnable(){public void run(){render();handler.postDelayed(this,250);}};
 public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("config",0);try{font=Typeface.createFromAsset(getAssets(),"SpaceGrotesk.ttf");}catch(Exception e){font=Typeface.DEFAULT;}build();
 if(!prefs.contains("language"))language(true);else if(state==null&&!prefs.contains("source"))intro();}
 int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
 void build(){
 LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(22),dp(22),dp(22));root.setBackgroundColor(BG);
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(root);setContentView(scroll);
 if(Build.VERSION.SDK_INT>=30)scroll.setOnApplyWindowInsetsListener((v,i)->{Insets s=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(s.left,s.top,s.right,s.bottom);return i;});
 TextView eyebrow=text(root,t("LOCAL BACKUP / XS3","SAUVEGARDE LOCALE / XS3"),11,MUTED);eyebrow.setLetterSpacing(.12f);
 LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);root.addView(heading);
 TextView name=new TextView(this);name.setText("Android2USB");name.setTextSize(29);name.setTextColor(INK);name.setTypeface(font);heading.addView(name,new LinearLayout.LayoutParams(0,-2,1));
 Button settings=new Button(this);settings.setText("⚙");settings.setTextSize(25);settings.setTextColor(BLUE);settings.setBackgroundColor(Color.TRANSPARENT);settings.setContentDescription(t("Settings","Paramètres"));heading.addView(settings,new LinearLayout.LayoutParams(dp(52),dp(52)));settings.setOnClickListener(v->settings());
 text(root,t("Your files. Your USB drive.","Vos fichiers. Votre clé USB."),17,MUTED);
 LinearLayout src=card(root);text(src,t("01 / SOURCE","01 / SOURCE"),11,BLUE);source=text(src,"",15,INK);srcButton=button(src,t("Choose source folder","Choisir le dossier source"),v->pick(1),false);
 LinearLayout dst=card(root);text(dst,t("02 / USB DESTINATION","02 / DESTINATION USB"),11,BLUE);dest=text(dst,"",15,INK);dstButton=button(dst,t("Choose USB folder","Choisir le dossier USB"),v->pick(2),false);
 copy=button(root,t("COPY TO USB  →","COPIE VERS USB  →"),v->startCopy(),true);
 copy.setBackgroundTintList(null);GradientDrawable copyBackground=new GradientDrawable();copyBackground.setColor(0xff153049);copyBackground.setCornerRadius(dp(12));copyBackground.setStroke(dp(1.5f),BLUE);
 copy.setBackground(new android.graphics.drawable.RippleDrawable(ColorStateList.valueOf(0x3346bfff),copyBackground,null));copy.setTextColor(INK);copy.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));copy.setTextSize(15);copy.setMinHeight(dp(60));copy.setPadding(dp(14),dp(10),dp(14),dp(10));
 android.graphics.drawable.Drawable copyIcon=getDrawable(R.drawable.ic_copy);copyIcon.setBounds(0,0,dp(40),dp(40));copy.setCompoundDrawablesRelative(copyIcon,null,null,null);copy.setCompoundDrawablePadding(dp(10));
 LinearLayout.LayoutParams copyLayout=new LinearLayout.LayoutParams(-1,-2);copyLayout.setMargins(dp(20),dp(16),dp(20),dp(18));copy.setLayoutParams(copyLayout);
 LinearLayout progress=card(root);status=text(progress,t("Ready","Prêt"),19,INK);
 bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setProgressTintList(ColorStateList.valueOf(BLUE));bar.setProgressBackgroundTintList(ColorStateList.valueOf(0xff233344));progress.addView(bar,new LinearLayout.LayoutParams(-1,dp(12)));
 detail=text(progress,"",13,MUTED);cancel=button(progress,t("Stop copy","Arrêter la copie"),v->{CopyService.cancelled=true;},false);
 text(root,t("Existing files are skipped. Source files stay on your phone. Subfolders are included.","Les fichiers présents sont ignorés. Les fichiers source restent sur le téléphone. Les sous-dossiers sont inclus."),13,MUTED);
 View spacer=new View(this);root.addView(spacer,new LinearLayout.LayoutParams(1,0,1));
 BrandView coffee=new BrandView(this,BrandView.Kind.COFFEE);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(dp(200),dp(48));cp.gravity=Gravity.CENTER_HORIZONTAL;cp.topMargin=dp(24);cp.bottomMargin=dp(8);root.addView(coffee,cp);coffee.setContentDescription(t("Buy me a coffee. Open the support page.","Offrez-moi un café. Ouvrir la page de soutien."));clickable(coffee,()->open("https://buymeacoffee.com/xscube"));
 LinearLayout footer=new LinearLayout(this);footer.setGravity(Gravity.CENTER_VERTICAL);root.addView(footer);
 BrandView logo=new BrandView(this,BrandView.Kind.LOGO);footer.addView(logo,new LinearLayout.LayoutParams(dp(72),dp(50)));logo.setContentDescription(t("XS3 website","Site XS3"));clickable(logo,()->open("https://www.xs3.ch"));
 TextView github=new TextView(this);github.setText("GitHub ↗");github.setTextSize(14);github.setTextColor(BLUE);github.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);github.setMinHeight(dp(48));footer.addView(github,new LinearLayout.LayoutParams(0,-2,1));clickable(github,()->open("https://github.com/mfarad/Android2USB"));
 render();}
 void clickable(View v,Runnable action){v.setFocusable(true);v.setClickable(true);v.setOnClickListener(w->action.run());}
 LinearLayout card(LinearLayout root){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(16),dp(10),dp(16),dp(10));GradientDrawable bg=new GradientDrawable();bg.setColor(0xff0c1722);bg.setStroke(dp(1),0xff29465d);bg.setCornerRadius(dp(8));p.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(12);lp.bottomMargin=dp(8);root.addView(p,lp);return p;}
 TextView text(LinearLayout parent,String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(7),0,dp(7));v.setTypeface(font);parent.addView(v);return v;}
 Button button(LinearLayout parent,String label,View.OnClickListener listener,boolean primary){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTypeface(font);b.setTextColor(primary?0xff06111c:INK);b.setBackgroundTintList(ColorStateList.valueOf(primary?BLUE:0xff153049));b.setMinHeight(dp(50));b.setOnClickListener(listener);parent.addView(b,new LinearLayout.LayoutParams(-1,-2));return b;}
 void language(boolean first){if(dialogOpen)return;dialogOpen=true;new AlertDialog.Builder(this).setTitle(first?"Language / Langue":t("Language","Langue")).setItems(new String[]{"English","Français"},(d,n)->{prefs.edit().putString("language",n==0?"en":"fr").apply();dialogOpen=false;build();if(first&&!prefs.contains("source"))intro();}).setCancelable(!first).setOnDismissListener(d->dialogOpen=false).show();}
 void intro(){new AlertDialog.Builder(this).setTitle(t("First setup","Première utilisation")).setMessage(t("Choose the source folder, usually DCIM/Camera. Then choose a folder on your USB drive.","Choisissez le dossier source, généralement DCIM/Camera. Puis choisissez un dossier sur la clé USB.")).setPositiveButton(t("Choose source","Choisir la source"),(d,w)->pick(1)).setNegativeButton(t("Later","Plus tard"),null).show();}
 void settings(){new AlertDialog.Builder(this).setTitle(t("Settings","Paramètres")).setItems(new String[]{t("Language: English","Langue : Français"),t("Source folder","Dossier source"),t("USB destination","Destination USB"),t("Privacy","Confidentialité")},(d,n)->{if(n==0)language(false);else if(n==3)privacy();else if(CopyService.running)error(t("Stop the copy before changing folders.","Arrêtez la copie avant de changer les dossiers."));else pick(n);}).show();}
 void privacy(){new AlertDialog.Builder(this).setTitle(t("Privacy","Confidentialité")).setMessage(t("Android2USB copies files locally. It has no ads, analytics or account. Folder access and language stay on this device. External links open your browser or another app, where that service’s privacy policy applies. Contact: info@xs3.ch.","Android2USB copie les fichiers localement. Aucun compte, publicité ou outil de suivi. Les dossiers autorisés et la langue restent sur cet appareil. Les liens externes ouvrent le navigateur ou une autre application. Leur politique de confidentialité s’applique. Contact : info@xs3.ch.")).setPositiveButton("OK",null).show();}
 void pick(int n){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);String old=prefs.getString(n==1?"source":"dest","");Uri initial=old.isEmpty()?Uri.parse("content://com.android.externalstorage.documents/document/primary%3ADCIM%2FCamera"):Uri.parse(old);if(n==1||!old.isEmpty())i.putExtra(DocumentsContract.EXTRA_INITIAL_URI,initial);try{startActivityForResult(i,n);}catch(ActivityNotFoundException e){error(t("No folder picker is available.","Aucun sélecteur de dossiers disponible."));}}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if((req!=1&&req!=2)||result!=RESULT_OK||data==null||data.getData()==null)return;try{Uri u=data.getData();String other=prefs.getString(req==1?"dest":"source","");if(!other.isEmpty()&&overlap(u,Uri.parse(other)))throw new Exception(t("Choose separate folders. Neither may contain the other.","Choisissez deux dossiers distincts. Aucun ne doit contenir l’autre."));
 if((data.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)!=0)getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);else getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);prefs.edit().putString(req==1?"source":"dest",u.toString()).apply();render();if(req==1&&!prefs.contains("dest"))pick(2);}catch(Exception e){error(e.getMessage());}}
 static boolean overlap(Uri a,Uri b){return a.getAuthority().equals(b.getAuthority())&&CopyRules.overlap(DocumentsContract.getTreeDocumentId(a),DocumentsContract.getTreeDocumentId(b));}
 void startCopy(){if(!prefs.contains("source")||!prefs.contains("dest")){error(t("Choose both folders first.","Choisissez les deux dossiers."));return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED&&!prefs.getBoolean("notificationAsked",false)){pendingCopy=true;prefs.edit().putBoolean("notificationAsked",true).apply();requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},3);}else launch();}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==3&&pendingCopy){pendingCopy=false;launch();}}
 void launch(){try{startForegroundService(new Intent(this,CopyService.class));}catch(Exception e){error(t("Cannot start the copy: ","Impossible de démarrer la copie : ")+e.getMessage());}}
 void open(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){error(t("No application can open this link.","Aucune application ne peut ouvrir ce lien."));}}
 void error(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("OK",null).show();}
 String label(String key){String s=prefs.getString(key,"");return s.isEmpty()?t("Not selected","Non sélectionné"):DocumentsContract.getTreeDocumentId(Uri.parse(s));}
 void render(){if(source==null)return;source.setText(label("source"));dest.setText(label("dest"));boolean busy=CopyService.running;srcButton.setEnabled(!busy);dstButton.setEnabled(!busy);copy.setEnabled(!busy);copy.setAlpha(busy?.45f:1f);cancel.setVisibility(busy?View.VISIBLE:View.GONE);bar.setIndeterminate(busy&&CopyService.scanning);bar.setMax(Math.max(1,CopyService.total));bar.setProgress(CopyService.done);status.setText(CopyService.status(this));detail.setText(CopyService.details(this));}
 protected void onResume(){super.onResume();handler.removeCallbacks(refresh);handler.post(refresh);}protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
